'use strict';

// MODULES //

var path = require( 'node:path' );
var randomUUID = require( 'node:crypto' ).randomUUID;
var fs = require( 'node:fs/promises' );


// MAIN //

/**
* Atomically writes a file without permitting replacement.
*
* @param {string} filePath - destination path
* @param {Buffer|string} bytes - file contents
* @returns {Promise<void>} promise
*/
async function writeNoClobber( filePath, bytes ) {
	var temporary;
	var handle;

	await fs.mkdir( path.dirname( filePath ), { 'recursive': true } );
	temporary = path.join( path.dirname( filePath ), '.' + path.basename( filePath ) + '.' + randomUUID() + '.tmp' );
	handle = await fs.open( temporary, 'wx', 0o600 );
	try {
		try {
			await handle.writeFile( bytes );
			await handle.sync();
		} finally {
			await handle.close();
		}
		try {
			await fs.link( temporary, filePath );
		} catch ( error ) {
			if ( error.code === 'EEXIST' ) {
				throw new Error( 'Refusing to overwrite output file: ' + filePath, {
					'cause': error
				} );
			}
			throw error;
		}
	} finally {
		await fs.unlink( temporary ).catch( function ignore() {} );
	}
}


// EXPORTS //

module.exports = writeNoClobber;
